CREATE DATABASE IF NOT EXISTS projeto_faculdade;
USE projeto_faculdade;

CREATE TABLE IF NOT EXISTS cursos (id INT PRIMARY KEY, nome VARCHAR(100) NOT NULL, sigla VARCHAR(20) NOT NULL, area VARCHAR(100) NOT NULL, carga_horaria INT NOT NULL, coordenador VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS usuarios (id INT PRIMARY KEY, nome VARCHAR(100) NOT NULL, login VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(100) NOT NULL UNIQUE, senha VARCHAR(50) NOT NULL, cargo VARCHAR(30) NOT NULL, tipo_monitor VARCHAR(30), matricula VARCHAR(50) UNIQUE, curso_id INT, FOREIGN KEY (curso_id) REFERENCES cursos(id));
CREATE TABLE IF NOT EXISTS periodos (id INT PRIMARY KEY, curso_id INT NOT NULL, numero INT NOT NULL, nome VARCHAR(100) NOT NULL, UNIQUE (curso_id, numero), FOREIGN KEY (curso_id) REFERENCES cursos(id));
CREATE TABLE IF NOT EXISTS materias (id INT PRIMARY KEY, periodo_id INT NOT NULL, nome VARCHAR(100) NOT NULL, professor_id INT, UNIQUE (periodo_id, nome), FOREIGN KEY (periodo_id) REFERENCES periodos(id), FOREIGN KEY (professor_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS participantes (materia_id INT NOT NULL, usuario_id INT NOT NULL, PRIMARY KEY (materia_id, usuario_id), FOREIGN KEY (materia_id) REFERENCES materias(id), FOREIGN KEY (usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS aulas (id INT PRIMARY KEY, materia_id INT NOT NULL, titulo VARCHAR(100) NOT NULL, data_aula VARCHAR(20), objetivo VARCHAR(200), FOREIGN KEY (materia_id) REFERENCES materias(id));
CREATE TABLE IF NOT EXISTS feedbacks (id INT PRIMARY KEY AUTO_INCREMENT, aula_id INT NOT NULL, estudante_id INT NOT NULL, nota INT NOT NULL CHECK (nota BETWEEN 0 AND 10), comentario VARCHAR(200), UNIQUE (aula_id, estudante_id), FOREIGN KEY (aula_id) REFERENCES aulas(id), FOREIGN KEY (estudante_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS materiais (id INT PRIMARY KEY, materia_id INT NOT NULL, titulo VARCHAR(100) NOT NULL, tipo VARCHAR(30) NOT NULL, referencia VARCHAR(300) NOT NULL, autor_id INT NOT NULL, FOREIGN KEY (materia_id) REFERENCES materias(id), FOREIGN KEY (autor_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS mensagens (id INT PRIMARY KEY, origem VARCHAR(20) NOT NULL, origem_id INT NOT NULL, autor_id INT NOT NULL, texto VARCHAR(500) NOT NULL, FOREIGN KEY (autor_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS grupos_estudo (id INT PRIMARY KEY, materia_id INT NOT NULL, nome VARCHAR(100) NOT NULL, aula_id INT, monitor_id INT, FOREIGN KEY (materia_id) REFERENCES materias(id), FOREIGN KEY (aula_id) REFERENCES aulas(id), FOREIGN KEY (monitor_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS grupos_estudo_alunos (grupo_id INT NOT NULL, estudante_id INT NOT NULL, PRIMARY KEY (grupo_id, estudante_id), FOREIGN KEY (grupo_id) REFERENCES grupos_estudo(id), FOREIGN KEY (estudante_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS grupos_estudo_monitores (grupo_id INT NOT NULL, monitor_id INT NOT NULL, PRIMARY KEY (grupo_id, monitor_id), FOREIGN KEY (grupo_id) REFERENCES grupos_estudo(id), FOREIGN KEY (monitor_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS pedidos_monitoria (id INT PRIMARY KEY, materia_id INT NOT NULL, estudante_id INT NOT NULL, aula_id INT, monitor_id INT, duvida VARCHAR(300) NOT NULL, status VARCHAR(30) NOT NULL, data_monitoria VARCHAR(20), horario VARCHAR(10), FOREIGN KEY (materia_id) REFERENCES materias(id), FOREIGN KEY (estudante_id) REFERENCES usuarios(id), FOREIGN KEY (aula_id) REFERENCES aulas(id), FOREIGN KEY (monitor_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS quizzes (id INT PRIMARY KEY, aula_id INT NOT NULL UNIQUE, titulo VARCHAR(100) NOT NULL, descricao VARCHAR(300), FOREIGN KEY (aula_id) REFERENCES aulas(id));
CREATE TABLE IF NOT EXISTS perguntas_quiz (id INT PRIMARY KEY, quiz_id INT NOT NULL, enunciado VARCHAR(500) NOT NULL, dificuldade VARCHAR(20) NOT NULL, FOREIGN KEY (quiz_id) REFERENCES quizzes(id));
CREATE TABLE IF NOT EXISTS alternativas_quiz (id INT PRIMARY KEY, pergunta_id INT NOT NULL, texto VARCHAR(255) NOT NULL, explicacao VARCHAR(500), correta BOOLEAN NOT NULL, FOREIGN KEY (pergunta_id) REFERENCES perguntas_quiz(id));
CREATE TABLE IF NOT EXISTS tentativas_quiz (id INT PRIMARY KEY, quiz_id INT NOT NULL, estudante_id INT NOT NULL, data_tentativa VARCHAR(30), acertos INT NOT NULL, total_perguntas INT NOT NULL, FOREIGN KEY (quiz_id) REFERENCES quizzes(id), FOREIGN KEY (estudante_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS respostas_quiz (id INT PRIMARY KEY, tentativa_id INT NOT NULL, pergunta_id INT NOT NULL, alternativa_id INT NOT NULL, acertou BOOLEAN NOT NULL, UNIQUE (tentativa_id, pergunta_id), FOREIGN KEY (tentativa_id) REFERENCES tentativas_quiz(id), FOREIGN KEY (pergunta_id) REFERENCES perguntas_quiz(id), FOREIGN KEY (alternativa_id) REFERENCES alternativas_quiz(id));
